import {renderGuide} from './guide.js';
import {demoNotes} from './demo-notes.js';

export function createContent(page, lang) {
const repo = 'https://github.com/lyhys12345/github-video-engine';
const t = (en, zh) => lang === 'zh' ? zh : en;
const arrow = '<span aria-hidden="true">↗</span>';
const play = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 5 11 7-11 7Z" fill="currentColor"/></svg>';
const href = (path) => `${lang === 'zh' ? '/zh' : ''}${path}`;
const doc = (path) => `${repo}/blob/main/docs/${path}.md`;
const external = (url, text, cls='') => `<a class="${cls}" href="${url}" target="_blank" rel="noopener noreferrer">${text} ${arrow}</a>`;
const demos = [
  {id:'engine-flagship', name:'GitHub Video Engine', category:'explainer', duration:'0:57', seconds:57.367, repo, label:['The story behind the tool','我们自己的产品故事'], description:['From a repository to a story worth sharing. See the complete idea in under a minute.','从一个仓库，到一条值得分享的视频。不到一分钟，了解我们的产品。'], detail:['A product film approved by the GitHub Video Engine creator, featuring OpenMAIC, repository screenshots and an illustrated workflow.','经 GitHub Video Engine 作者认可的产品介绍片，包含 OpenMAIC、仓库截图与流程示意。'], color:'mint'},
  {id:'artcraft-demo', name:'ArtCraft', category:'creative', duration:'0:25', seconds:24.533, repo:'https://github.com/storytold/artcraft', label:['A pose becomes a new scene.','一个姿势，变成新场景'], description:['A pose becomes a scene. A creative tool explained through a visual transformation.','从一个姿势到一个场景，用画面的变化解释创作工具。'], detail:['Uses an official pose-editing example. The demo distinguishes pose references and model-cost considerations.','使用官方姿势编辑示例，片中说明姿势参考和模型成本。'], color:'peach'},
  {id:'voicestudio-demo', name:'VoiceStudio', category:'creative', duration:'0:41', seconds:41.131, repo:'https://github.com/debpalash/VoiceStudio', label:['A familiar voice. A new line.','熟悉的音色，新的台词'], description:['An audio comparison gives a voice tool a concrete, memorable introduction.','用真实声音对比，让语音工具的作用一听就明白。'], detail:['Includes official pre-generated audio. Application and game sequences include illustrations, not a claim of live tool operation.','包含官方预生成音频；应用和游戏画面含示意，不代表现场运行工具。'], color:'lavender'},
  {id:'openmaic-b-demo', name:'OpenMAIC', category:'learning', duration:'0:46', seconds:45.833, repo:'https://github.com/THU-MAIC/OpenMAIC', label:['A classroom where AI joins the conversation.','AI 老师和同学，一起讨论'], description:['Meet a classroom where the conversation is part of the lesson.','当 AI 老师和同学开始讨论，课堂会是什么样？'], detail:['Uses official classroom footage. The course-generation sequence is illustrative.','使用官方课堂素材，课程生成过程为示意。'], color:'lilac'},
  {id:'worldknow-demo', name:'The World We Know', zhName:'山海所知', category:'explainer', duration:'0:43', seconds:43.435, repo:'https://github.com/Greenere/the-world-we-know', label:['See how the known world changed over time.','看看人们认识的世界，如何随时间改变。'], description:['A giraffe opens the story; real map interactions explain what the project does.','用长颈鹿引出好奇心，再通过真实地图交互展示项目用途。'], detail:['Real product map interactions and repository imagery, alongside labeled mechanism illustrations.','真实产品地图交互与仓库画面，机制示意在片中标注。'], color:'sand'}
];
const name = d => lang === 'zh' && d.zhName ? d.zhName : d.name;
const pair = a => t(...a);
function nav() {
 return `<a class="skip" href="#main">${t('Skip to content','跳到正文')}</a><header class="header"><a class="brand" href="${href('/')}" aria-label="GitHub Video Engine ${t('home','首页')}"><img src="/assets/favicon.svg" alt="" width="31" height="31"><span>GitHub <strong>Video Engine</strong></span></a><nav class="navigation" id="navigation" aria-label="${t('Main navigation','主导航')}">${[['home','/',t('Overview','首页')],['showcase','/showcase/',t('Showcase','作品库')],['guide','/guide/',t('Get started','使用指南')]].map(([id,url,label])=>`<a ${page===id?'aria-current="page"':''} href="${href(url)}">${label}</a>`).join('')}</nav><div class="nav-actions"><a href="${lang==='en'?'/zh':''}${page==='home'?'/':`/${page}/`}" id="language" class="language" aria-label="${t('Switch to Chinese','切换为英文')}"><span aria-hidden="true">◎</span> ${t('中文','EN')}</a>${external(repo,'GitHub','repo-link')}<button id="menu" class="menu" aria-controls="navigation" aria-expanded="false" aria-label="${t('Open navigation','展开导航')}"><span></span><span></span></button></div></header>`;
}
function card(d, index=0) {
 return `<article class="film-card ${d.color}" data-category="${d.category}"><a href="/assets/${d.id}.mp4" class="poster-button" data-play="${d.id}" aria-label="${t('Play','播放')} ${name(d)}"><div class="poster-wrap"><img src="/assets/${d.id}.jpg" alt="${name(d)} ${t('video preview','视频预览')}" loading="lazy" width="360" height="640"><span class="film-index">0${index+1} / ${t('PROJECT STORY','项目故事')}</span><span class="play-orb">${play}</span><span class="duration">${d.duration}</span></div></a><div class="film-info"><div class="film-title"><h3>${name(d)}</h3><span aria-hidden="true">↗</span></div><p>${pair(d.label)}</p><div class="film-extra"><p>${pair(d.description)}</p>${external(d.repo,t('Source repository','项目仓库'))}</div></div></article>`;
}
const steps = [
 ['01', ['Share the repository','给出仓库链接'], ['A GitHub URL, your audience, and the story you want to tell.','一个 GitHub 链接，加上受众和你想表达的重点。'], 'github.com / your-name / your-project'],
 ['02', ['Find the story','找到值得讲的故事'], ['Research the source. Pick a useful result. Build a narrative around evidence.','读来源、找亮点，从有证据支撑的结果组织叙事。'], 'Sources → insight → story'],
 ['03', ['Make it yours','先看脚本，再做决定'], ['Review the complete narration and storyboard. Generation starts after your approval.','审核完整旁白与分镜。你确认后，才开始生成视频。'], 'Script + storyboard → your approval'],
 ['04', ['Bring it to life','把故事变成视频'], ['Render, review and revise. Keep the video and an editable engine project.','生成、审阅与修改，拿到成片和可编辑的引擎项目。'], 'MP4 + editable project + sources']
];
function home() {
 return `<main id="main"><section class="hero-v2 container"><div class="hero-copy"><p class="eyebrow">${t('GITHUB REPOSITORY → SHORT VIDEO','GITHUB 仓库 → 短视频')}</p><h1>${t('Your GitHub repo.<br> <em>A story in motion.</em>','你的 GitHub 项目，<br> <em>值得被看见。</em>')}</h1><p class="hero-lead">${t('Turn a repository into a video for TikTok, Reels or Xiaohongshu. Research, script review and editable output, in your local Codex workspace.','把仓库变成适合小红书、TikTok 和 Reels 的视频。在本地 Codex 中研究项目、审核脚本，最后拿到可编辑的作品。')}</p><div class="actions"><a href="/assets/artcraft-demo.mp4" class="button dark" data-play="artcraft-demo">${play} ${t('Watch a real example','看真实成片')} <span class="button-time">0:25</span></a><a class="start-link" href="${href('/guide/')}">${t('Start in Codex','在 Codex 中开始')} <span aria-hidden="true">›</span></a></div><p class="hero-context">${t("English subtitles available · Verified on","可选英文字幕 · 已验证环境：")} <span class="keep-together">Windows + Codex</span></p></div>
 <div class="cinema"><div class="cinema-copy"><p class="cinema-kicker">${t('MADE WITH GITHUB VIDEO ENGINE','用 GITHUB VIDEO ENGINE 制作')}</p><h2>${t('A pose.<br> A new scene.','一个姿势，<br> 新的场景。')}</h2><p>${t('See how a creative tool becomes a 25-second introduction.','看看一个创作工具，如何被讲成 25 秒的项目介绍。')}</p>${external('https://github.com/storytold/artcraft','storytold / artcraft','cinema-source')}</div><div class="cinema-media"><video id="hero-motion" muted loop playsinline preload="none" poster="/assets/artcraft-excerpt.jpg" aria-label="${t('Muted excerpt from the ArtCraft example','ArtCraft 作品的无声节选')}" data-src="/assets/artcraft-excerpt.mp4"></video></div><div class="cinema-caption"><span>${t('ArtCraft explainer · Chinese audio','ArtCraft 讲解短片 · 中文配音')}</span><button id="motion-toggle" aria-label="${t('Play preview motion','播放动态预览')}"><span aria-hidden="true">▶</span></button></div></div><div class="hero-footnote"><span>${t('A local agent skill. You approve the script before generation.','本地 Agent Skill。先审核脚本，再生成视频。')}</span><a href="/assets/engine-flagship.mp4" class="text-button" data-play="engine-flagship">${t('Meet the engine','了解引擎')} ${play} <span>0:57</span></a></div></section>
 <section class="section container works-section"><div class="section-top"><div><p class="eyebrow">${t('A FEW STORIES ALREADY TOLD','看看已经讲出的故事')}</p><h2>${t('Different projects.<br> <em>Different ways to shine.</em>','不同项目，<br> <em>各有看点。</em>')}</h2></div><a class="inline-link" href="${href('/showcase/')}">${t('All five films','查看全部五条作品')} ${arrow}</a></div><div class="film-grid home-films">${[demos[2],demos[3],demos[4]].map(card).join('')}</div><p class="media-note">${t('All five films have English subtitle translations and were made with human direction and review.','五条中文示例均附英文翻译字幕，经过人工指导与审阅。')}</p></section>
 <section class="workflow-section"><div class="container"><div class="section-top"><div><p class="eyebrow">${t('FROM REPOSITORY TO READY TO SHARE','从仓库，到值得分享的作品')}</p><h2>${t('You bring the project.<br> <em>Shape the story together.</em>','你带来项目，<br> <em>一起把故事讲好。</em>')}</h2></div><p class="section-aside">${t('The skill connects research, storytelling and rendering. You keep the important decisions.','Skill 连接研究、叙事和渲染。重要的决定，始终由你来做。')}</p></div><ol class="workflow-static" aria-label="${t('Workflow steps','创作步骤')}">${steps.map(s=>`<li><span class="step-number" aria-hidden="true">${s[0]}</span><h3>${pair(s[1])}</h3><p>${pair(s[2])}</p></li>`).join('')}</ol><div class="workflow"><div class="workflow-tabs" role="tablist" aria-label="${t('Workflow steps','创作步骤')}">${steps.map((s,i)=>`<button role="tab" id="step-${i}" aria-controls="workflow-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-step="${i}"><span>${s[0]}</span><strong>${pair(s[1])}</strong><b aria-hidden="true">›</b></button>`).join('')}</div><div id="workflow-panel" class="workflow-panel" role="tabpanel" aria-labelledby="step-0" tabindex="0">${workflowPanel(0)}</div></div></div></section>
 <section class="section container owner-section"><div class="section-top"><div><p class="eyebrow">${t('BUILT FOR THE AUTHOR','为项目作者设计')}</p><h2>${t('Your facts. Your voice.<br> <em>Your final say.</em>','事实有出处，故事有个性。<br> <em>决定权在你。</em>')}</h2></div></div><div class="owner-grid"><article><div class="owner-visual source-visual" aria-hidden="true"><span>README.md</span><span>src /</span><div class="trace-line"></div><strong>${t('A claim with a source.','每个事实，都有来源。')}</strong></div><h3>${t('Know what backs the story.','知道每句话的依据。')}</h3><p>${t('Research connects claims to repository evidence. Distinguish real product footage from an illustrated explanation.','研究将事实与仓库证据关联。真实产品画面和机制示意，各自标清。')}</p></article><article><div class="owner-visual review-visual"><span>${t('SCRIPT REVIEW','脚本审核')}</span><p>${t('“Show the result first. Then explain the idea.”','“先展示结果，再解释原理。”')}</p><strong>✓ ${t('Your approval comes first','确认之后，才生成')}</strong></div><h3>${t('Make the choices that matter.','表达方式，由你来定。')}</h3><p>${t('Choose the audience, length, style and voice. Review the narration and every shot before generation.','选择受众、时长、风格与声音。生成之前，看完整旁白与每个镜头。')}</p></article><article><div class="owner-visual export-visual" aria-hidden="true"><span><b>▶</b> MP4</span><span><b>≡</b> ${t('Editable story','可编辑故事')}</span><span><b>↗</b> ${t('Source records','来源记录')}</span></div><h3>${t('Keep the project behind the film.','成片之外，保留创作过程。')}</h3><p>${t('Supported exports retain story, animation and caption timing. Revise the engine project as your repository evolves.','支持的导出保留故事、动画与字幕时间安排。仓库更新后，可以继续修改引擎项目。')}</p></article></div><p class="media-note">${t('Workflow illustrations. Exported projects use the engine’s formats, not Premiere or CapCut formats.','流程示意。导出使用引擎项目格式，并非 Premiere 或剪映工程。')}</p></section>
 <section class="faq-section section container"><div><p class="eyebrow">${t('BEFORE YOUR FIRST STORY','开始第一个故事之前')}</p><h2>${t('A little clarity.<br> <em>A better start.</em>','先了解清楚，<br> <em>再轻松开始。</em>')}</h2></div><div class="faq">${faq()}</div></section>${cta()}</main>`;
}
function faq() {
 const items=[
 [t('Is this a website that generates videos?','能直接在这个网站生成视频吗？'),t('This site showcases the work. The engine runs locally with a coding agent: you share a repository, review a script, then generate and refine the video.','这里是产品展示网站。引擎在本地配合编程 Agent 运行：提供仓库、审阅脚本，然后生成和修改视频。')],
 [t('Do I need a separate paid model API?','一定要付费模型 API 吗？'),t('The Codex session workflow uses your existing agent environment, without a separate model API key. Your host account and usage terms still apply. Free local narration needs its own compatible runtime; you can also import authorized audio or start silently.','Codex 会话流程使用你已有的 Agent 环境，不需要另配模型 API 密钥；平台账号与用量规则仍然适用。免费本地配音需兼容的运行环境，也可以导入有权使用的音频或先做无声预览。')],
 [t('Will I get the voices heard in these demos?','能直接用示例里的声音吗？'),t('Not automatically. Some demos use private voice configurations that are not distributed. Public local presets and authorized audio import provide separate starting options.','不会自动获得。部分示例使用的私人音色配置不随项目分发。新用户可选择公开本地音色，或导入有权使用的音频。')],
 [t('What can I edit after export?','导出后还能修改什么？'),t('The engine project retains structured story, animation, captions and source records for supported workflows. This is not a promise of a Premiere or CapCut project export.','支持的流程会保留结构化故事、动画、字幕与来源记录。这是引擎项目，并非 Premiere 或剪映工程导出。')]
 ]; return items.map(([q,a])=>`<details><summary>${q}<span aria-hidden="true">+</span></summary><p>${a}</p></details>`).join('');
}
function cta() {return `<section class="closing container"><p class="eyebrow">${t('GOOD PROJECTS DESERVE TO BE SEEN','好项目，值得被看见')}</p><h2>${t('Your next release.<br> <em>With a story to share.</em>','下一次发布，<br> <em>带上一条好故事。</em>')}</h2><a class="button lime" href="${href('/guide/')}">${t('Get started','开始使用')} ${arrow}</a><span class="closing-mark" aria-hidden="true">↗</span></section>`;}
function showcase() {
 return `<main id="main" class="showcase-page"><section class="page-intro container"><p class="eyebrow">${t('THE SHOWCASE / ACTUAL OUTPUT','作品库 / 真实产出')}</p><h1>${t('See what your repo<br> <em>could become.</em>','看看你的项目，<br> <em>能被怎样讲述。</em>')}</h1><p>${t('Start with ArtCraft: 25 seconds, one visual idea. Then explore voice tools, AI learning and interactive maps.','先看 ArtCraft：25 秒，讲清一个直观的创意。再看看声音工具、AI 课堂和交互地图。')}</p></section><section class="container showcase-collection"><div class="collection-toolbar"><div class="filters" role="group" aria-label="${t('Filter videos','筛选视频')}">${[['all',t('All films','全部作品')],['creative',t('Creative tools','创作工具')],['learning',t('Learning','学习工具')],['explainer',t('Explainers','项目讲解')]].map(([id,label])=>`<button data-filter="${id}" aria-pressed="${id==='all'}">${label}</button>`).join('')}</div><span id="result-count" aria-live="polite">${t('5 films','5 条作品')}</span></div><div class="film-grid showcase-films">${[demos[1],demos[2],demos[3],demos[4],demos[0]].map(card).join('')}</div><p class="media-note">${t('All five films have English subtitle translations, source links and footage notes. The original Chinese narration and on-screen text remain. These examples were made with human direction and review.','五条作品均附英文翻译字幕、项目链接与素材说明，保留原始中文配音和画面文字。这些示例均经过人工指导与审阅。')}</p></section><section class="showcase-note container"><span>✳</span><div><h2>${t('A reference, not a promise of one-click perfection.','真实参考，持续打磨。')}</h2><p>${t('These films include human direction and review. The skill brings that research, planning and revision process into an editable workflow. Every repository still deserves its own story.','这些作品经过人工指导与审阅。Skill 将研究、策划与返修组织成可编辑的流程，但每个仓库仍然需要适合自己的故事。')}</p></div><a class="inline-link" href="${href('/guide/')}">${t('See how it works','了解使用方式')} ${arrow}</a></section>${cta()}</main>`;
}
const esc = value => value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function codeBlock(id, text, label) {return `<div class="code-block"><div class="code-label"><span>${label}</span><button data-copy="${id}">${t('Copy','复制')}</button></div><pre><code id="${id}">${esc(text)}</code></pre></div>`;}
function guide() { return renderGuide({t,href,doc,external,codeBlock,cta: () => cta().replace(href("/guide/"),"#brief")}).replace('class="agent-panel"></div>', `class="agent-panel">${agentPanel('codex')}</div>`); }
function footer() {return `<footer class="footer container"><a class="footer-brand" href="${href('/')}"><img src="/assets/favicon.svg" width="28" height="28" alt="">GitHub Video Engine</a><p>${t('Built for the stories behind the code.','让代码背后的故事，被更多人看见。')}</p><div><a href="${href('/showcase/')}">${t('Showcase','作品库')}</a><a href="${href('/guide/')}">${t('Guide','使用指南')}</a>${external(repo,'GitHub')}</div></footer><dialog id="film-dialog" aria-labelledby="film-dialog-title"><button class="dialog-close" aria-label="${t('Close video','关闭视频')}">✕</button><div class="dialog-layout"><div class="video-shell"><video controls playsinline preload="none"></video></div><div class="dialog-info"><p class="eyebrow">${t('FROM THE SHOWCASE','作品库')}</p><h2 id="film-dialog-title"></h2><p id="film-description"></p><div class="dialog-meta"></div><p id="film-provenance"></p><a id="film-source" class="inline-link" target="_blank" rel="noopener noreferrer"></a><div id="film-notes" class="film-notes"></div><p class="dialog-note" id="film-language-note"></p><p class="play-error" role="status"></p></div></div></dialog><div class="toast" role="status" aria-live="polite"></div>`;}

function workflowPanel(index){const s=steps[index];return `<span class="panel-overline">${t('EXAMPLE WORKFLOW','流程示意')} / ${s[0]}</span><div class="workflow-visual"><span class="workflow-symbol" aria-hidden="true">${['↗','✳','✓','▶'][index]}</span><code>${s[3]}</code></div><h3>${pair(s[1])}</h3><p>${pair(s[2])}</p><div class="step-progress">${steps.map((_,i)=>`<i class="${i===index?'active':''}"></i>`).join('')}</div>`;}
function agentPanel(agent){return agent==='codex'?`<h3>${t('Use your existing Codex session.','使用现有 Codex 会话。')}</h3><p>${t('The repository includes the github-explainer skill and project instructions. Open the engine folder and ask in ordinary language. No separate API key or global skill copy is needed for this route.','仓库已包含 github-explainer Skill 与项目指令。打开引擎文件夹，直接用自然语言提出需求，无需额外 API 密钥或复制全局 Skill。')}</p>${external(doc('codex-user-path-v1'),t('Codex walkthrough','Codex 使用说明'),'inline-link')}`:`<h3>${t('A project-local Claude entry is included.','已包含 Claude 项目入口。')}</h3><p>${t('Open the engine checkout. CLAUDE.md and its skill wrapper point to the shared workflow. The entry has static checks; a real Claude end-to-end media session remains unverified.','打开引擎目录。CLAUDE.md 与 Skill 包装入口连接到共用流程。入口已做静态检查，真实 Claude 端到端媒体会话仍未验证。')}</p>${external(doc('claude-code-user-path-v1'),t('Claude Code notes','Claude Code 说明'),'inline-link')}`;}
function body(){return nav()+(page==='home'?home():page==='showcase'?showcase():guide())+footer();}
return {body,t,href,doc,demos,name,pair,steps,workflowPanel,agentPanel,demoNotes};
}
